264:     // A7 写数据生效（跨周期）：全字节掩码写入时，BVALID 后寄存器必须等于写数据
265:     // （掩码写（WSTRB 非全 1）只更新部分字节，无法与原始数据整体比对，故仅全掩码时检查）
266:     always @(posedge ACLK) begin
267:         if (ARESETN && S_AXI_BVALID && (wstrb_d == {(DATA_W/8){1'b1}})) begin
268:             case (waddr_d[ADDR_W-1:2])
269:                 2'd0: assert (reg0 == wdata_d);
270:                 2'd1: assert (reg1 == wdata_d);
271:                 2'd2: assert (reg2 == wdata_d);
